H.background();
const a = P.a;
const v = H.plot2d({ xMin: 0, xMax: 8, yMin: -10, yMax: 20 });
v.grid(); v.axes();
const v0 = 2;
const vAt = x => v0 + a * x;
const tc = (t % 8);
const pts = [[0, 0]];
for (let i = 0; i <= 40; i++) {
  const x = (tc) * (i / 40);
  pts.push([x, vAt(x)]);
}
pts.push([tc, 0]);
v.path(pts, { color: H.colors.accent2, fill: "rgba(244,162,89,0.25)", close: true });
v.fn(vAt, { color: H.colors.accent, width: 3 });
const disp = v0 * tc + 0.5 * a * tc * tc;
v.dot(tc, vAt(tc), { r: 6, fill: H.colors.warn });
H.text("Velocity-time graph: area = displacement", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("v(t) = v0 + a*t   (v0 = 2 m/s)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("a = " + a.toFixed(1) + " m/s^2", 24, 74, { color: H.colors.sub, size: 13 });
H.text("t = " + tc.toFixed(1) + " s   v = " + vAt(tc).toFixed(1) + " m/s", 24, 96, { color: H.colors.accent, size: 13 });
H.text("displacement = area = " + disp.toFixed(1) + " m", 24, 118, { color: H.colors.accent2, size: 13 });

H.background();
const v0 = P.v0, a = P.a;
const x0 = 0;
const period = 6;
const tc = (t % period);
const xt = x0 + v0 * tc + 0.5 * a * tc * tc;
const vt = v0 + a * tc;
const xMin = -20, xMax = 60;
const px = H.map(Math.max(xMin, Math.min(xMax, xt)), xMin, xMax, 80, H.W - 40);
const trackY = 320;
H.line(80, trackY, H.W - 40, trackY, { color: H.colors.grid, width: 2 });
for (let xm = xMin; xm <= xMax; xm += 10) {
  const tx = H.map(xm, xMin, xMax, 80, H.W - 40);
  H.line(tx, trackY - 6, tx, trackY + 6, { color: H.colors.axis, width: 1 });
  H.text(xm + "", tx, trackY + 22, { color: H.colors.sub, size: 11, align: "center" });
}
H.circle(px, trackY - 18, 14, { fill: H.colors.accent });
const vScale = 3;
H.arrow(px, trackY - 18, px + vt * vScale, trackY - 18, { color: H.colors.warn, width: 3 });
const view = H.plot2d({ xMin: 0, xMax: period, yMin: -20, yMax: 60, box: { x: 90, y: 380, w: H.W - 140, h: 150 } });
view.grid(); view.axes();
view.fn(s => x0 + v0 * s + 0.5 * a * s * s, { color: H.colors.accent2, width: 2 });
view.dot(tc, xt, { r: 5, fill: H.colors.warn });
H.text("Constant acceleration: x = x0 + v0*t + 1/2 a t^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("x0 = 0 m,  v0 = " + v0.toFixed(1) + " m/s,  a = " + a.toFixed(1) + " m/s^2", 24, 52, { color: H.colors.sub, size: 13 });
H.text("t = " + tc.toFixed(1) + " s", 24, 74, { color: H.colors.sub, size: 13 });
H.text("x = " + xt.toFixed(1) + " m   v = " + vt.toFixed(1) + " m/s", 24, 96, { color: H.colors.accent, size: 13 });

H.background();
const g = 9.8;
const h0 = P.h0;
const tFall = Math.sqrt(2 * h0 / g);
const period = tFall + 1.2;
const tc = (t % period);
const tf = Math.min(tc, tFall);
const y = h0 - 0.5 * g * tf * tf;
const vy = -g * tf;
const groundY = 500, topY = 80;
const yMax = Math.max(h0, 1);
const py = H.map(Math.max(0, y), 0, yMax, groundY, topY);
const ballX = H.W / 2;
H.line(120, groundY, H.W - 120, groundY, { color: H.colors.grid, width: 3 });
H.text("ground", H.W - 120, groundY + 18, { color: H.colors.sub, size: 11, align: "right" });
for (let i = 0; i <= 4; i++) {
  const hv = yMax * i / 4;
  const ty = H.map(hv, 0, yMax, groundY, topY);
  H.line(115, ty, 125, ty, { color: H.colors.axis, width: 1 });
  H.text(hv.toFixed(0) + " m", 108, ty, { color: H.colors.sub, size: 11, align: "right", baseline: "middle" });
}
H.line(ballX, topY, ballX, groundY, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.circle(ballX, py, 16, { fill: H.colors.accent });
H.arrow(ballX, py, ballX, py - vy * 4, { color: H.colors.warn, width: 3 });
H.text("Free fall: y = h0 - 1/2 g t^2,  v = -g t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("g = 9.8 m/s^2,  released from rest", 24, 52, { color: H.colors.sub, size: 13 });
H.text("h0 = " + h0.toFixed(1) + " m   t_fall = " + tFall.toFixed(2) + " s", 24, 74, { color: H.colors.sub, size: 13 });
H.text("t = " + tf.toFixed(2) + " s", 24, 96, { color: H.colors.sub, size: 13 });
H.text("y = " + Math.max(0, y).toFixed(1) + " m   v = " + vy.toFixed(1) + " m/s", 24, 118, { color: H.colors.accent, size: 13 });

H.background();
const g = 9.8;
const speed = P.speed;
const angDeg = P.angle;
const ang = angDeg * Math.PI / 180;
const vx = speed * Math.cos(ang);
const vy = speed * Math.sin(ang);
const tFlight = Math.max(0.001, 2 * vy / g);
const range = vx * tFlight;
const maxH = (vy * vy) / (2 * g);
const xMax = Math.max(range * 1.1, 1);
const yMax = Math.max(maxH * 1.3, 1);
const view = H.plot2d({ xMin: 0, xMax: xMax, yMin: 0, yMax: yMax });
view.grid(); view.axes();
const pts = [];
for (let i = 0; i <= 50; i++) {
  const tt = tFlight * i / 50;
  pts.push([vx * tt, vy * tt - 0.5 * g * tt * tt]);
}
view.path(pts, { color: H.colors.accent, width: 3 });
const tc = (t % (tFlight + 0.6));
const tp = Math.min(tc, tFlight);
const xp = vx * tp;
const yp = Math.max(0, vy * tp - 0.5 * g * tp * tp);
view.dot(xp, yp, { r: 7, fill: H.colors.warn });
view.dot(range / 2, maxH, { r: 5, fill: H.colors.good });
view.text("apex", range / 2, maxH + yMax * 0.05, { color: H.colors.good, size: 11, align: "center" });
H.text("Projectile: range R = v^2 sin(2a)/g", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("g = 9.8 m/s^2,  launch from ground", 24, 52, { color: H.colors.sub, size: 13 });
H.text("v = " + speed.toFixed(1) + " m/s   angle = " + angDeg.toFixed(0) + " deg", 24, 74, { color: H.colors.sub, size: 13 });
H.text("R = " + range.toFixed(1) + " m   H = " + maxH.toFixed(1) + " m   t_flight = " + tFlight.toFixed(2) + " s", 24, 96, { color: H.colors.accent, size: 13 });

H.background();
const vBoat = P.vboat;
const vRiver = P.vriver;
const Rx = vRiver;
const Ry = vBoat;
const Rmag = Math.sqrt(Rx * Rx + Ry * Ry);
const ang = Math.atan2(Ry, Rx) * 180 / Math.PI;
const lim = Math.max(vBoat, vRiver, 1) * 1.4;
const view = H.plot2d({ xMin: -lim, xMax: lim, yMin: -0.3 * lim, yMax: lim * 1.2 });
view.grid(); view.axes();
view.arrow(0, 0, 0, vBoat, { color: H.colors.accent, width: 3 });
view.text("boat " + vBoat.toFixed(1), 0.05 * lim, vBoat * 0.6, { color: H.colors.accent, size: 12 });
view.arrow(0, vBoat, vRiver, vBoat, { color: H.colors.good, width: 3 });
view.text("river " + vRiver.toFixed(1), vRiver * 0.5, vBoat + 0.05 * lim, { color: H.colors.good, size: 12 });
view.arrow(0, 0, Rx, Ry, { color: H.colors.warn, width: 4 });
const period = 6;
const s = (t % period) / period;
view.dot(Rx * s, Ry * s, { r: 7, fill: H.colors.violet });
H.text("Relative velocity: v_boat + v_river = v_resultant", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Vectors add tip-to-tail (boat across + current downstream)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("v_boat = " + vBoat.toFixed(1) + " m/s   v_river = " + vRiver.toFixed(1) + " m/s", 24, 74, { color: H.colors.sub, size: 13 });
H.text("|v| = " + Rmag.toFixed(2) + " m/s   theta = " + ang.toFixed(1) + " deg from downstream", 24, 96, { color: H.colors.warn, size: 13 });

H.background();
const W = H.W;
const F = P.F, m = Math.max(0.1, P.m);
const a = F / m;
const groundY = 360;
H.line(40, groundY, W - 40, groundY, { color: H.colors.grid, width: 2 });
const cx = W / 2;
const span = 220;
const xpos = cx + span * Math.sin(t * 0.9) * H.clamp(a / 12, 0.05, 1);
const bw = 90, bh = 64;
const bx = xpos - bw / 2, by = groundY - bh;
H.rect(bx, by, bw, bh, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 6 });
H.text(m.toFixed(1) + " kg", xpos, by + bh / 2, { color: H.colors.ink, size: 14, align: "center", baseline: "middle" });
const dir = Math.cos(t * 0.9) >= 0 ? 1 : -1;
const alen = H.clamp(Math.abs(F) * 6, 12, 180) * Math.sign(F || 1) * dir;
H.arrow(xpos, by + bh / 2, xpos + alen, by + bh / 2, { color: H.colors.accent2, width: 4 });
H.text("F", xpos + alen + 8 * Math.sign(alen || 1), by + bh / 2 - 12, { color: H.colors.accent2, size: 14, align: "center" });
const aarr = H.clamp(a * 12, 8, 200) * dir;
H.arrow(xpos, by - 18, xpos + aarr, by - 18, { color: H.colors.good, width: 3 });
H.text("a", xpos + aarr + 8 * Math.sign(aarr || 1), by - 30, { color: H.colors.good, size: 13, align: "center" });
H.text("Newton's 2nd law:  F = m a", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Same force on a heavier block gives a smaller acceleration.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("F = " + F.toFixed(1) + " N", 24, 84, { color: H.colors.accent2, size: 14 });
H.text("m = " + m.toFixed(1) + " kg", 24, 104, { color: H.colors.sub, size: 14 });
H.text("a = F/m = " + a.toFixed(2) + " m/s^2", 24, 124, { color: H.colors.good, size: 14 });

H.background();
const W = H.W;
const m = 5, g = 9.8, mu = 0.4;
const Fapp = P.Fapp;
const Wt = m * g;
const N = Wt;
const fricMax = mu * N;
const moving = Math.abs(Fapp) > fricMax;
const fric = moving ? -Math.sign(Fapp) * fricMax : -Fapp;
const net = Fapp + fric;
const groundY = 380;
H.line(40, groundY, W - 40, groundY, { color: H.colors.grid, width: 2 });
const cx = W / 2;
const sway = (net / 30) * 40 * Math.sin(t * 1.2);
const bx = cx + H.clamp(sway, -120, 120);
const by = groundY;
const s = 70;
H.rect(bx - s / 2, by - s, s, s, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 6 });
const ccx = bx, ccy = by - s / 2;
H.circle(ccx, ccy, 4, { fill: H.colors.ink });
const sc = 2.2;
H.arrow(ccx, ccy, ccx, ccy + Wt * sc * 0.5, { color: H.colors.warn, width: 4 });
H.text("W=" + Wt.toFixed(0) + "N", ccx + 8, ccy + Wt * sc * 0.5, { color: H.colors.warn, size: 12 });
H.arrow(ccx, ccy, ccx, ccy - N * sc * 0.5, { color: H.colors.good, width: 4 });
H.text("N=" + N.toFixed(0) + "N", ccx + 8, ccy - N * sc * 0.5, { color: H.colors.good, size: 12 });
H.arrow(ccx, ccy, ccx + Fapp * sc, ccy, { color: H.colors.accent2, width: 4 });
H.text("F=" + Fapp.toFixed(0) + "N", ccx + Fapp * sc + 6 * Math.sign(Fapp || 1), ccy - 12, { color: H.colors.accent2, size: 12, align: "center" });
H.arrow(ccx, ccy + 16, ccx + fric * sc, ccy + 16, { color: H.colors.violet, width: 4 });
H.text("f=" + Math.abs(fric).toFixed(0) + "N", ccx + fric * sc + 6 * Math.sign(fric || -1), ccy + 34, { color: H.colors.violet, size: 12, align: "center" });
H.text("Free-body diagram:  net F = F_app - f", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Up/down forces balance; horizontal net force = applied minus friction.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("net = " + net.toFixed(1) + " N  (" + (moving ? "moving" : "static") + ")", 24, 84, { color: H.colors.accent, size: 14 });

H.background();
const W = H.W;
const m = 4, g = 9.8, mus = 0.5, muk = 0.3;
const N = m * g;
const fsMax = mus * N;
const fk = muk * N;
const Fapp = P.Fapp;
const moving = Fapp > fsMax;
const fric = moving ? fk : Math.min(Fapp, fsMax);
const net = Fapp - fric;
const a = moving ? net / m : 0;
const groundY = 360;
H.line(40, groundY, W - 40, groundY, { color: H.colors.grid, width: 2 });
for (let i = 0; i < 24; i++) {
  const gx = 50 + i * 35;
  H.line(gx, groundY, gx - 10, groundY + 10, { color: H.colors.grid, width: 1 });
}
const cx = W / 2;
const slide = moving ? 120 * Math.sin(t * 1.4) : 0;
const bx = cx + H.clamp(slide, -150, 150);
const s = 72;
H.rect(bx - s / 2, groundY - s, s, s, { fill: H.colors.panel, stroke: moving ? H.colors.good : H.colors.accent, width: 2, radius: 6 });
const ccy = groundY - s / 2;
const sc = 3.0;
H.arrow(bx, ccy, bx + Fapp * sc, ccy, { color: H.colors.accent2, width: 4 });
H.text("F_app", bx + Fapp * sc + 8, ccy - 10, { color: H.colors.accent2, size: 12 });
H.arrow(bx, ccy + 18, bx - fric * sc, ccy + 18, { color: H.colors.violet, width: 4 });
H.text("f", bx - fric * sc - 12, ccy + 30, { color: H.colors.violet, size: 12 });
const barX = 24, barY = 430, barW = W - 48;
H.line(barX, barY, barX + barW, barY, { color: H.colors.grid, width: 2 });
H.text("0", barX, barY + 20, { color: H.colors.sub, size: 11 });
const fsX = barX + barW * H.clamp(fsMax / 40, 0, 1);
H.line(fsX, barY - 8, fsX, barY + 8, { color: H.colors.warn, width: 2 });
H.text("μs·N=" + fsMax.toFixed(1) + "N", fsX, barY - 14, { color: H.colors.warn, size: 11, align: "center" });
const fX = barX + barW * H.clamp(Fapp / 40, 0, 1);
H.circle(fX, barY, 6, { fill: H.colors.accent2 });
H.text("Static vs kinetic friction:  f_s ≤ μs·N,  f_k = μk·N", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Block stays put until F exceeds μs·N, then kinetic friction μk·N acts.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("F = " + Fapp.toFixed(1) + " N -> " + (moving ? "MOVING, a=" + a.toFixed(2) + " m/s^2" : "STATIC, f=" + fric.toFixed(1) + " N"), 24, 84, { color: moving ? H.colors.good : H.colors.accent, size: 14 });

H.background();
const deg = H.clamp(P.theta, 0, 80);
const th = deg * Math.PI / 180;
const m = 4, g = 9.8;
const Wt = m * g;
const par = Wt * Math.sin(th);
const perp = Wt * Math.cos(th);
const ax = 120, ay = 420;
const baseLen = 520;
const topX = ax + baseLen * Math.cos(th);
const topY = ay - baseLen * Math.sin(th);
H.path([[ax, ay], [ax + baseLen, ay], [topX, topY]], { color: H.colors.grid, width: 2, fill: H.colors.panel, close: true });
H.line(ax, ay, topX, topY, { color: H.colors.accent, width: 3 });
const f = 0.25 + 0.5 * (0.5 + 0.5 * Math.sin(t * 0.8));
const px = ax + baseLen * f * Math.cos(th);
const py = ay - baseLen * f * Math.sin(th);
const ux = Math.cos(th), uy = -Math.sin(th);
const nx = Math.sin(th), ny = Math.cos(th);
const s = 50;
const bcx = px - nx * (s / 2 - 10);
const bcy = py - ny * (s / 2 - 10);
H.rect(bcx - s / 2, bcy - s / 2, s, s, { fill: H.colors.panel, stroke: H.colors.accent2, width: 2, radius: 5 });
const sc = 3.2;
H.arrow(bcx, bcy, bcx, bcy + Wt * sc * 0.5, { color: H.colors.warn, width: 4 });
H.text("mg", bcx + 6, bcy + Wt * sc * 0.5, { color: H.colors.warn, size: 12 });
H.arrow(bcx, bcy, bcx - ux * par * sc, bcy - uy * par * sc, { color: H.colors.good, width: 4 });
H.text("mg sinθ", bcx - ux * par * sc - 30, bcy - uy * par * sc, { color: H.colors.good, size: 12 });
H.arrow(bcx, bcy, bcx + nx * perp * sc, bcy + ny * perp * sc, { color: H.colors.violet, width: 4 });
H.text("mg cosθ", bcx + nx * perp * sc + 6, bcy + ny * perp * sc, { color: H.colors.violet, size: 12 });
H.text(deg.toFixed(0) + "°", ax + 70, ay - 12, { color: H.colors.sub, size: 13 });
H.text("Block on an incline:  components of mg", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Gravity splits into mg·sinθ down the slope and mg·cosθ into the surface.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("θ=" + deg.toFixed(0) + "°  mg·sinθ=" + par.toFixed(1) + "N  mg·cosθ=" + perp.toFixed(1) + "N", 24, 84, { color: H.colors.accent, size: 14 });

H.background();
const W = H.W;
const g = 9.8;
const m1 = Math.max(0.1, P.m1);
const m2 = Math.max(0.1, P.m2);
const a = (m2 - m1) * g / (m1 + m2);
const T = 2 * m1 * m2 * g / (m1 + m2);
const pcx = W / 2, pcy = 110, pr = 40;
H.circle(pcx, pcy, pr, { fill: H.colors.panel, stroke: H.colors.accent, width: 3 });
H.circle(pcx, pcy, 5, { fill: H.colors.ink });
const lx = pcx - pr, rx = pcx + pr;
const amp = 70;
const disp = amp * Math.sin(t * 1.1) * Math.sign(a || 1);
const y1 = 250 - disp;
const y2 = 250 + disp;
H.line(lx, pcy, lx, y1, { color: H.colors.sub, width: 2 });
H.line(rx, pcy, rx, y2, { color: H.colors.sub, width: 2 });
function box(x, y, mass, col) {
  const s = 30 + 26 * H.clamp(mass / 10, 0, 1);
  H.rect(x - s / 2, y, s, s, { fill: H.colors.panel, stroke: col, width: 2, radius: 5 });
  H.text(mass.toFixed(1) + "kg", x, y + s / 2, { color: H.colors.ink, size: 12, align: "center", baseline: "middle" });
}
box(lx, y1, m1, H.colors.accent2);
box(rx, y2, m2, H.colors.good);
const sc = 1.4;
H.arrow(lx, y1, lx, y1 - H.clamp(T * sc, 14, 90), { color: H.colors.violet, width: 3 });
H.arrow(rx, y2, rx, y2 - H.clamp(T * sc, 14, 90), { color: H.colors.violet, width: 3 });
H.text("T", lx - 16, y1 - 30, { color: H.colors.violet, size: 12 });
H.text("T", rx + 6, y2 - 30, { color: H.colors.violet, size: 12 });
H.text("Atwood machine:  a = (m2-m1)g/(m1+m2),  T = 2 m1 m2 g/(m1+m2)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Unequal masses share one rope; heavier side falls, tension is equal throughout.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("a = " + a.toFixed(2) + " m/s^2   T = " + T.toFixed(1) + " N", 24, 84, { color: H.colors.accent, size: 14 });
H.text((m2 > m1 ? "m2 falls" : m2 < m1 ? "m1 falls" : "balanced"), 24, 104, { color: H.colors.sub, size: 13 });

H.background();
const g = 9.8, m = P.m, a = P.a;
const N = m * (g + a);
const w = m * g;
H.text("Apparent weight: N = m(g + a)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Scale reads the NORMAL force, not the true weight mg", 24, 52, { color: H.colors.sub, size: 13 });
const cx = H.W * 0.5;
const cy0 = H.H * 0.5;
const bob = 16 * Math.sin(t * 1.2) * (a >= 0 ? 1 : -1);
const cy = cy0 + bob;
const carW = 150, carH = 230;
const left = cx - carW / 2, top = cy - carH / 2;
H.rect(left, top, carW, carH, { stroke: H.colors.axis, width: 3, radius: 8 });
const bx = cx - 34, by = top + carH - 70;
H.rect(bx, by, 68, 60, { fill: H.colors.accent, stroke: H.colors.ink, width: 2, radius: 6 });
H.text("m", cx, by + 34, { color: H.colors.bg, size: 18, weight: 700, align: "center", baseline: "middle" });
H.line(cx, by + 60, cx, top + carH, { color: H.colors.axis, width: 4 });
const wScale = w * 0.18 + 8;
H.arrow(cx, by, cx, by - Math.min(wScale, 90), { color: H.colors.warn, width: 4 });
H.text("mg = " + w.toFixed(0) + " N", cx - 80, by - 24, { color: H.colors.warn, size: 13, align: "right" });
const nScale = N * 0.18 + 8;
H.arrow(cx, by + 60, cx, by + 60 - Math.min(nScale, 110), { color: H.colors.good, width: 4 });
H.text("N = " + N.toFixed(0) + " N", cx + 80, by + 30, { color: H.colors.good, size: 13 });
const aLabel = a > 0.05 ? "accel UP" : a < -0.05 ? "accel DOWN" : "no accel";
H.text("a = " + a.toFixed(1) + " m/s^2  (" + aLabel + ")", 24, 76, { color: H.colors.accent2, size: 13 });
