H.text("Lines leave + and enter -; they never cross. Density shows field strength.", 24, 52, { color: H.colors.sub, size: 13 });
const xp = cx - d * scale, xm = cx + d * scale;
const yp = cy, ym = cy;
function field(px, py) {
  let ex = 0, ey = 0;
  let rx = px - xp, ry = py - yp, r2 = rx * rx + ry * ry + 25, r = Math.sqrt(r2);
  ex += rx / (r2 * r); ey += ry / (r2 * r);
  rx = px - xm; ry = py - ym; r2 = rx * rx + ry * ry + 25; r = Math.sqrt(r2);
  ex -= rx / (r2 * r); ey -= ry / (r2 * r);
  return [ex, ey];
}
const nLines = 12, startR = 16;
for (let i = 0; i < nLines; i++) {
  const a0 = (i / nLines) * H.TAU + 0.0001;
  let px = xp + Math.cos(a0) * startR;
  let py = yp + Math.sin(a0) * startR;
  const pts = [[px, py]];
  const step = 5;
  for (let s = 0; s < 220; s++) {
    const f = field(px, py);
    const mag = Math.hypot(f[0], f[1]);
    if (mag < 1e-12) break;
    px += (f[0] / mag) * step;
    py += (f[1] / mag) * step;
    pts.push([px, py]);
    if (Math.hypot(px - xm, py - ym) < startR) break;
    if (px < -50 || px > H.W + 50 || py < -50 || py > H.H + 50) break;
  }
  H.path(pts, { color: H.colors.accent, width: 1.5 });
  const m = Math.floor(((t * 0.5 + i / nLines) % 1) * (pts.length - 1));
  if (pts[m]) H.circle(pts[m][0], pts[m][1], 3, { fill: H.colors.yellow });
}
