const v = H.plot2d({ xMin: 0, xMax: 4, yMin: -2, yMax: 2, box: { x: 60, y: 90, w: H.W * 0.52, h: H.H - 170 } });
v.grid(); v.axes();
// flux ramps with slope=rate; we draw a triangle-wave-ish flux that sweeps so the dot moves and loops
const period = 4;
const tt = t % period;
// Phi(t) = rate*(t - 2) clamped into view, plus we sweep a probe dot along it
v.fn(x => Math.max(-2, Math.min(2, rate * (x - 2))), { color: H.colors.accent, width: 3 });
const px = tt;
const py = Math.max(-2, Math.min(2, rate * (px - 2)));
v.dot(px, py, { r: 7, fill: H.colors.accent2 });
v.text("Phi(t), slope = dPhi/dt", 0.2, 1.7, { color: H.colors.accent, size: 12 });
v.text("t (s)", 3.5, -0.25, { color: H.colors.sub, size: 11 });
// RIGHT: induced-EMF bar + a simple loop with a glowing bulb whose brightness ~ |EMF|
const bx = H.W * 0.62, by = 100, bw = H.W - bx - 50, bh = H.H - 190;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 1, radius: 8 });
H.text("induced loop", bx + 10, by - 8, { color: H.colors.sub, size: 12 });
const lcx = bx + bw / 2, lcy = by + bh / 2;
// loop
H.circle(lcx, lcy, 52, { stroke: H.colors.violet, width: 3 });
// current direction depends on sign of emf; animate a charge dot around the loop, speed ~ |emf|
const speed = Math.min(4, Math.abs(emf) * 0.8 + 0.2);
const dirSign = emf >= 0 ? 1 : -1;
const ca = dirSign * t * speed;
H.circle(lcx + 52 * Math.cos(ca), lcy + 52 * Math.sin(ca), 7, { fill: H.colors.good });
// bulb brightness
const bright = Math.min(1, Math.abs(emf) / (Math.abs(Nturns) * 2 + 0.5));
H.circle(lcx, lcy, 14 + 10 * bright, { fill: H.colors.yellow, stroke: H.colors.axis, width: 1 });
H.text("EMF bar:", bx + 10, by + bh + 22, { color: H.colors.sub, size: 12 });
const ebarMax = Math.abs(Nturns) * 2 + 0.5;
const ebar = Math.min(1, Math.abs(emf) / ebarMax) * (bw - 90);
H.rect(bx + 80, by + bh + 12, ebar, 12, { fill: emf >= 0 ? H.colors.good : H.colors.warn });
H.text("EMF = -N*dPhi/dt = " + emf.toFixed(2) + " V   (N=" + Nturns.toFixed(0) + ", dPhi/dt=" + rate.toFixed(2) + " Wb/s)", 24, 76, { color: H.colors.sub, size: 13 });

H.background();
const speed = P.speed; // magnet oscillation speed scale (m/s)
const pole = P.pole;   // +1 = N pole facing coil, -1 = S pole facing coil
H.text("Lenz's law: induced current opposes the CHANGE in flux", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Approaching N pole -> coil presents its N face and repels the magnet", 24, 52, { color: H.colors.sub, size: 13 });
const coilX = H.W * 0.62, cy = H.H / 2 + 10;
const coilH = 150;
for (let k = 0; k < 7; k++) {
  const y = cy - coilH / 2 + coilH * k / 6;
  H.circle(coilX, y, 46, { stroke: H.colors.grid, width: 1 });
}
H.rect(coilX - 50, cy - coilH / 2 - 10, 100, coilH + 20, { stroke: H.colors.violet, width: 2, radius: 8 });
H.text("coil", coilX - 14, cy - coilH / 2 - 18, { color: H.colors.violet, size: 12 });
// magnet oscillates toward/away so it stays in frame; its instantaneous velocity drives the physics
const w = 0.4 + Math.abs(speed) * 0.25;
const amp = 150;
const mx = (coilX - 250) + amp * (1 + Math.sin(t * w)) / 2;
const vinst = amp * w * Math.cos(t * w) / 2;   // +x = toward coil
const approaching = vinst > 0;
const mw = 90, mh = 46;
const nFacingCoil = pole >= 0;                  // N pole on the coil (right) side?
H.rect(mx - mw / 2, cy - mh / 2, mw / 2, mh, { fill: nFacingCoil ? H.colors.warn : H.colors.accent });
H.rect(mx, cy - mh / 2, mw / 2, mh, { fill: nFacingCoil ? H.colors.accent : H.colors.warn });
H.text(nFacingCoil ? "S" : "N", mx - mw / 4, cy, { color: H.colors.ink, size: 14, align: "center", baseline: "middle", weight: 700 });
H.text(nFacingCoil ? "N" : "S", mx + mw / 4, cy, { color: H.colors.ink, size: 14, align: "center", baseline: "middle", weight: 700 });
H.arrow(mx, cy - mh / 2 - 16, mx + (vinst >= 0 ? 36 : -36), cy - mh / 2 - 16, { color: H.colors.yellow, width: 2 });
H.text("v", mx + (vinst >= 0 ? 40 : -50), cy - mh / 2 - 16, { color: H.colors.yellow, size: 12, baseline: "middle" });
// Sign of dPhi/dt: facing-pole base sign s, times +1 if approaching (|flux| growing) else -1.
const s = nFacingCoil ? 1 : -1;
const dPhi = s * (approaching ? 1 : -1);
// Coil opposes: near face repels an approaching magnet (same pole), attracts a receding one.
const nearFaceN = approaching ? nFacingCoil : !nFacingCoil;
H.text("coil near face: " + (nearFaceN ? "N" : "S"), coilX - 36, cy + coilH / 2 + 24, { color: nearFaceN ? H.colors.warn : H.colors.accent, size: 13 });
// induced current dot circulating; direction flips with sign of dPhi/dt, speed ~ |induced I|
const Iind = Math.min(4, Math.abs(speed) * 0.9 + 0.3);
const ca = (dPhi > 0 ? 1 : -1) * t * Iind;
H.circle(coilX + 46 * Math.cos(ca), cy + 46 * Math.sin(ca), 7, { fill: H.colors.good });
// Lenz force on magnet: pushes it away when approaching, pulls it back when receding
const fdir = approaching ? -1 : 1;
H.arrow(mx + mw / 2 + 6, cy, mx + mw / 2 + 6 + fdir * 34, cy, { color: H.colors.accent2, width: 2 });
H.text("F_coil", mx + mw / 2 + 10, cy - 14, { color: H.colors.accent2, size: 11 });
const motion = approaching ? "approaching -> flux rising -> coil REPELS" : "receding -> flux falling -> coil ATTRACTS";
H.text(motion + "   (|I_induced| ~ " + Iind.toFixed(1) + ", speed=" + speed.toFixed(1) + " m/s)", 24, 76, { color: H.colors.sub, size: 13 });

H.background();
const B = P.B, L = P.L, v = P.v;
H.text("Motional EMF:  EMF = B L v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A rod sliding on rails through B sweeps area, inducing an EMF", 24, 52, { color: H.colors.sub, size: 13 });
const railL = 240, railR = 760, railTop = 140, railBot = 140 + 160;
for (let i = 0; i < 8; i++) {
  for (let j = 0; j < 4; j++) {
    const fx = railL + 30 + i * 64;
    const fy = railTop + 22 + j * 40;
    H.circle(fx, fy, 2, { fill: H.colors.violet });
    H.text("x", fx - 4, fy + 26, { color: H.colors.grid, size: 11 });
  }
}
H.text("B into page", railL, railTop - 14, { color: H.colors.violet, size: 12 });
H.line(railL, railTop, railR, railTop, { color: H.colors.axis, width: 3 });
H.line(railL, railBot, railR, railBot, { color: H.colors.axis, width: 3 });
const span = (railR - 60) - (railL + 60);
const xr = (railL + 60) + (span * 0.5) * (1 + Math.sin(t * 0.8));
H.line(xr, railTop - 6, xr, railBot + 6, { color: H.colors.accent2, width: 5 });
const dir = Math.cos(t * 0.8) >= 0 ? 1 : -1;
H.arrow(xr, (railTop + railBot) / 2, xr + dir * 46, (railTop + railBot) / 2, { color: H.colors.good, width: 3 });
H.text("v", xr + dir * 30, (railTop + railBot) / 2 - 12, { color: H.colors.good, size: 13 });
const emf = B * L * v;
H.rect(railL - 36, railTop, 36, railBot - railTop, { stroke: H.colors.sub, width: 2, radius: 4 });
H.text("EMF", railL - 60, (railTop + railBot) / 2, { color: H.colors.sub, size: 12, align: "right" });
H.text("EMF = B*L*v = " + emf.toFixed(2) + " V", 24, 80, { color: H.colors.accent, size: 14 });
H.text("B = " + B.toFixed(2) + " T   L = " + L.toFixed(2) + " m   v = " + v.toFixed(2) + " m/s", 24, 100, { color: H.colors.sub, size: 13 });
H.legend([{ label: "B field (into page)", color: H.colors.violet }, { label: "rod velocity v", color: H.colors.good }], 560, 470);

H.background();
const w = P.w, e0 = P.e0;
H.text("AC generator:  EMF = e0 sin(w t)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A coil rotating in B gives a sinusoidal EMF; e0 = N*B*A*w is the peak", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 180, cy = 300, R = 90;
H.text("B field", cx - 70, cy - 130, { color: H.colors.violet, size: 12 });
for (let i = -2; i <= 2; i++) {
  H.line(cx + i * 30, cy - 120, cx + i * 30, cy + 120, { color: H.colors.grid, width: 1 });
}
const ang = w * t;
const ex = Math.cos(ang) * R, ey = Math.sin(ang) * R * 0.45;
H.path([[cx - ex, cy - ey], [cx + ex, cy + ey]], { color: H.colors.accent2, width: 5 });
H.circle(cx - ex, cy - ey, 6, { fill: H.colors.good });
H.circle(cx + ex, cy + ey, 6, { fill: H.colors.warn });
H.text("coil", cx - 18, cy + 140, { color: H.colors.sub, size: 12 });
const vv = H.plot2d({ xMin: 0, xMax: 8, yMin: -1.2, yMax: 1.2, box: { x: 420, y: 120, w: 440, h: 320 } });
vv.grid(); vv.axes();
vv.fn(x => e0 * Math.sin(w * x), { color: H.colors.accent, width: 3 });
const tw = t % 8;
vv.dot(tw, e0 * Math.sin(w * tw), { r: 6, fill: H.colors.warn });
const emf = e0 * Math.sin(ang);
H.text("EMF = " + emf.toFixed(2) + " V", 24, 80, { color: H.colors.accent, size: 14 });
H.text("e0 = " + e0.toFixed(2) + " V (peak)   w = " + w.toFixed(2) + " rad/s   wt = " + ang.toFixed(2) + " rad", 24, 100, { color: H.colors.sub, size: 13 });
vv.text("e0 sin(w t)", 0.4, e0 * 0.9, { color: H.colors.accent, size: 12 });

H.background();
const f = P.f, doSlider = P.do;
H.text("Concave mirror:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Image distance di and magnification m = -di/do vary with object distance do", 24, 52, { color: H.colors.sub, size: 13 });
const xV = 720, yAx = 320;
H.line(120, yAx, 820, yAx, { color: H.colors.axis, width: 1 });
const mpts = [];
for (let i = -90; i <= 90; i += 6) {
  const a = i * Math.PI / 180;
  mpts.push([xV - (1 - Math.cos(a)) * 40, yAx + Math.sin(a) * 110]);
}
H.path(mpts, { color: H.colors.sub, width: 3 });
const scale = 9;
const doVal = Math.max(2, doSlider + 6 * Math.sin(t * 0.5));
const xObj = xV - doVal * scale;
const hObj = 60;
H.arrow(xObj, yAx, xObj, yAx - hObj, { color: H.colors.good, width: 3 });
H.text("object", xObj - 16, yAx + 18, { color: H.colors.good, size: 12 });
const xF = xV - f * scale;
H.circle(xF, yAx, 4, { fill: H.colors.yellow });
H.text("F", xF - 3, yAx + 18, { color: H.colors.yellow, size: 12 });
let diStr, mStr;
const denom = (1 / f) - (1 / doVal);
if (Math.abs(denom) < 1e-4) {
  diStr = "di -> infinity (object at F)";
  H.text("rays emerge parallel: no image forms", 24, 124, { color: H.colors.warn, size: 13 });
} else {
  const di = 1 / denom;
  const m = -di / doVal;
  const xImg = xV - di * scale;
  const hImg = m * hObj;
  const xImgC = Math.max(130, Math.min(810, xImg));
  H.arrow(xImgC, yAx, xImgC, yAx - hImg, { color: H.colors.warn, width: 3 });
  H.text(di > 0 ? "real image" : "virtual image", xImgC - 20, yAx + 34, { color: H.colors.warn, size: 12 });
  diStr = "di = " + di.toFixed(1) + " cm";
  mStr = "m = " + m.toFixed(2);
  H.text("m = -di/do = " + m.toFixed(2) + (m < 0 ? "  (inverted)" : "  (upright)"), 24, 124, { color: H.colors.accent2, size: 13 });
}
H.text(diStr, 24, 80, { color: H.colors.accent, size: 14 });
H.text("f = " + f.toFixed(1) + " cm   do = " + doVal.toFixed(1) + " cm", 24, 102, { color: H.colors.sub, size: 13 });
H.legend([{ label: "object", color: H.colors.good }, { label: "image", color: H.colors.warn }], 120, 470);

H.background();
const th1deg = P.th1, n1 = P.n1, n2 = P.n2;
H.text("Snell's law:  n1 sin(th1) = n2 sin(th2)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Light bends toward the normal when entering a denser (higher n) medium", 24, 52, { color: H.colors.sub, size: 13 });
const ix = 450, iy = 300;
H.line(120, iy, 820, iy, { color: H.colors.axis, width: 2 });
H.rect(120, iy, 700, 180, { fill: H.colors.panel });
H.text("medium 1  n1 = " + n1.toFixed(2), 140, iy - 14, { color: H.colors.sub, size: 12 });
H.text("medium 2  n2 = " + n2.toFixed(2), 140, iy + 24, { color: H.colors.sub, size: 12 });
H.line(ix, iy - 160, ix, iy + 160, { color: H.colors.grid, width: 1, dash: [6, 6] });
H.text("normal", ix + 6, iy - 150, { color: H.colors.grid, size: 11 });
const th1 = (Math.max(5, Math.min(80, th1deg + 18 * Math.sin(t * 0.5)))) * Math.PI / 180;
const Lr = 180;
const ax = ix - Lr * Math.sin(th1), ay = iy - Lr * Math.cos(th1);
H.arrow(ax, ay, ix, iy, { color: H.colors.accent, width: 3 });
H.text("incident", ax - 10, ay - 8, { color: H.colors.accent, size: 12 });
const sinth2 = (n1 / n2) * Math.sin(th1);
let th2deg;
if (sinth2 > 1) {
  const rx = ix + Lr * Math.sin(th1), ry = iy - Lr * Math.cos(th1);
  H.arrow(ix, iy, rx, ry, { color: H.colors.warn, width: 3 });
  H.text("TOTAL INTERNAL REFLECTION", ix - 40, iy - 170, { color: H.colors.warn, size: 12 });
  th2deg = NaN;
  H.text("sin(th2) = (n1/n2) sin(th1) > 1  -> no refraction", 24, 124, { color: H.colors.warn, size: 13 });
} else {
  const th2 = Math.asin(sinth2);
  const bx = ix + Lr * Math.sin(th2), by = iy + Lr * Math.cos(th2);
  H.arrow(ix, iy, bx, by, { color: H.colors.good, width: 3 });
  H.text("refracted", bx + 4, by + 6, { color: H.colors.good, size: 12 });
  th2deg = th2 * 180 / Math.PI;
  H.text("th2 = " + th2deg.toFixed(1) + " deg", 24, 124, { color: H.colors.good, size: 13 });
}
H.text("th1 = " + (th1 * 180 / Math.PI).toFixed(1) + " deg", 24, 80, { color: H.colors.accent, size: 14 });
H.text("n1 sin th1 = " + (n1 * Math.sin(th1)).toFixed(3) + "   (invariant across interface)", 24, 102, { color: H.colors.sub, size: 13 });

H.background();
const th1deg = P.th1, n1 = P.n1, n2 = P.n2;
H.text("Total internal reflection:  sin(thc) = n2/n1", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("From dense to rare (n1>n2), beyond the critical angle thc light fully reflects", 24, 52, { color: H.colors.sub, size: 13 });
const ix = 450, iy = 280;
H.line(120, iy, 820, iy, { color: H.colors.axis, width: 2 });
H.rect(120, iy, 700, 200, { fill: H.colors.panel });
H.text("dense  n1 = " + n1.toFixed(2), 140, iy + 24, { color: H.colors.sub, size: 12 });
H.text("rare  n2 = " + n2.toFixed(2), 140, iy - 14, { color: H.colors.sub, size: 12 });
H.line(ix, iy - 150, ix, iy + 170, { color: H.colors.grid, width: 1, dash: [6, 6] });
const ratio = n2 / n1;
let thc = ratio < 1 ? Math.asin(ratio) : Math.PI / 2;
const thcDeg = thc * 180 / Math.PI;
const Lc = 175;
const cxp = ix + Lc * Math.sin(thc), cyp = iy + Lc * Math.cos(thc);
H.line(ix, iy, cxp, cyp, { color: H.colors.yellow, width: 1, dash: [4, 4] });
H.text("thc", cxp + 4, cyp, { color: H.colors.yellow, size: 11 });
const th1 = (Math.max(5, Math.min(85, th1deg + 22 * Math.sin(t * 0.5)))) * Math.PI / 180;
const Lr = 175;
const ax = ix - Lr * Math.sin(th1), ay = iy + Lr * Math.cos(th1);
H.arrow(ax, ay, ix, iy, { color: H.colors.accent, width: 3 });
H.text("incident", ax - 10, ay + 14, { color: H.colors.accent, size: 12 });
const sinth2 = (n1 / n2) * Math.sin(th1);
let status;
if (sinth2 >= 1) {
  const rx = ix + Lr * Math.sin(th1), ry = iy + Lr * Math.cos(th1);
  H.arrow(ix, iy, rx, ry, { color: H.colors.warn, width: 4 });
  H.text("reflected (100%)", rx + 4, ry, { color: H.colors.warn, size: 12 });
  status = "th1 >= thc  ->  TOTAL INTERNAL REFLECTION";
  H.text(status, 24, 124, { color: H.colors.warn, size: 13 });
} else {
  const th2 = Math.asin(sinth2);
  const bx = ix + Lr * Math.sin(th2), by = iy - Lr * Math.cos(th2);
  H.arrow(ix, iy, bx, by, { color: H.colors.good, width: 3 });
  H.text("refracted out", bx + 4, by, { color: H.colors.good, size: 12 });
  const rx = ix + Lr * 0.5 * Math.sin(th1), ry = iy + Lr * 0.5 * Math.cos(th1);
  H.line(ix, iy, rx, ry, { color: H.colors.warn, width: 1, dash: [3, 3] });
  status = "th1 < thc  ->  refracts (partial reflection)";
  H.text(status, 24, 124, { color: H.colors.good, size: 13 });
}
H.text("thc = " + thcDeg.toFixed(1) + " deg", 24, 80, { color: H.colors.yellow, size: 14 });
H.text("th1 = " + (th1 * 180 / Math.PI).toFixed(1) + " deg    sin(thc) = n2/n1 = " + ratio.toFixed(3), 24, 102, { color: H.colors.sub, size: 13 });

H.background();
const W = H.W, Hh = H.H;
const f = P.f;
const dov = Math.max(P.dov, 0.2);
const cx = W * 0.5, ay = Hh * 0.52;
const ppu = 9;
H.line(40, ay, W - 40, ay, { color: H.colors.axis, width: 1 });
const lensH = 150;
H.line(cx, ay - lensH/2, cx, ay + lensH/2, { color: H.colors.accent, width: 3 });
H.path([[cx-8, ay-lensH/2+10],[cx, ay-lensH/2],[cx+8, ay-lensH/2+10]], { color: H.colors.accent, width: 2 });
H.path([[cx-8, ay+lensH/2-10],[cx, ay+lensH/2],[cx+8, ay+lensH/2-10]], { color: H.colors.accent, width: 2 });
const fx = Math.abs(f) * ppu;
H.circle(cx - fx, ay, 3, { fill: H.colors.yellow });
H.circle(cx + fx, ay, 3, { fill: H.colors.yellow });
H.text("F", cx - fx, ay + 16, { color: H.colors.sub, size: 11, align: "center" });
H.text("F", cx + fx, ay + 16, { color: H.colors.sub, size: 11, align: "center" });
const hoBase = 6;
const ho = hoBase * (0.7 + 0.3 * Math.sin(t * 1.2));
const ox = cx - dov * ppu;
const otop = ay - ho * ppu;
H.arrow(ox, ay, ox, otop, { color: H.colors.good, width: 3 });
let di, hi, valid = true;
const inv = 1/f - 1/dov;
if (Math.abs(inv) < 1e-4) { valid = false; di = Infinity; hi = 0; }
else { di = 1/inv; hi = -di/dov * ho; }
const ix = cx + di * ppu;
const itop = ay - hi * ppu;
H.line(ox, otop, cx, otop, { color: H.colors.accent2, width: 1.5 });
if (valid && isFinite(ix)) {
  H.line(cx, otop, ix, itop, { color: H.colors.accent2, width: 1.5 });
  H.line(ox, otop, ix, itop, { color: H.colors.violet, width: 1.5 });
}
if (valid && isFinite(ix) && Math.abs(ix - cx) < W) {
  H.arrow(ix, ay, ix, itop, { color: H.colors.warn, width: 3 });
}
const m = valid ? -di/dov : 0;
H.text("Thin lens:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("do = " + dov.toFixed(1) + " cm,  f = " + f.toFixed(1) + " cm", 24, 52, { color: H.colors.sub, size: 13 });
if (valid && isFinite(di)) {
  H.text("di = " + di.toFixed(1) + " cm   m = " + m.toFixed(2) + (di>0?"  (real)":"  (virtual)"), 24, 72, { color: H.colors.yellow, size: 13 });
} else {
  H.text("Object at focal point: image at infinity", 24, 72, { color: H.colors.warn, size: 13 });
}

H.background();
const W = H.W, Hh = H.H;
const d = P.d;
const lam = P.lambda;
const dm = Math.max(d, 0.5) * 1e-6;
const lamm = Math.max(lam, 100) * 1e-9;
const v = H.plot2d({ xMin: -3, xMax: 3, yMin: 0, yMax: 1.25 });
v.grid(); v.axes();
const I = (thetaDeg) => {
  const th = thetaDeg * Math.PI / 180;
  const phi = Math.PI * dm * Math.sin(th) / lamm;
  return Math.cos(phi) * Math.cos(phi);
};
v.fn(I, { color: H.colors.accent, width: 2.5 });
for (let m = -5; m <= 5; m++) {
  const s = m * lamm / dm;
  if (Math.abs(s) <= 1) {
    const thDeg = Math.asin(s) * 180 / Math.PI;
    if (thDeg >= -3 && thDeg <= 3) {
      v.line(thDeg, 0, thDeg, 1, { color: H.colors.yellow, width: 1, dash: [4,4] });
      v.text("m=" + m, thDeg, 1.12, { color: H.colors.sub, size: 10, align: "center" });
    }
  }
