const vib = 4 * Math.sin(t * (1 + bo)) * (1 / bo); // stiffer (higher bo) vibrates less
const x1 = cx - sep / 2 - vib, x2 = cx + sep / 2 + vib;
// bond lines (bo of them, stacked)
for (let i = 0; i < bo; i++) {
  const off = (i - (bo - 1) / 2) * 12;
  H.line(x1, cy + off, x2, cy + off, { color: H.colors.accent, width: 4 });
}
H.circle(x1, cy, 34, { fill: H.colors.panel, stroke: H.colors.ink, width: 2 });
H.circle(x2, cy, 34, { fill: H.colors.panel, stroke: H.colors.ink, width: 2 });
H.text("C", x1, cy + 1, { color: H.colors.ink, size: 20, align: "center", baseline: "middle", weight: 700 });
H.text("C", x2, cy + 1, { color: H.colors.ink, size: 20, align: "center", baseline: "middle", weight: 700 });
