}
H.text("attraction", cx, cy - 24, { color: d.color, size: 12, align: "center" });
// boiling-point thermometer bar (relative), animated pulse
const bpRel = d.strength / 3; // 0..1 schematic
const barX = 120, barTop = 360, barBot = 470, barW = 50;
H.rect(barX, barTop, barW, barBot - barTop, { stroke: H.colors.grid, width: 1 });
