], H.W - 230, 110);

H.background();
// q1, q2 = ionic charge magnitudes (cation +, anion -); r = ionic separation (radius sum) in arbitrary units
let q1 = P.q1, q2 = P.q2, r = P.r;
if (!(r > 0.1)) r = 0.1; // guard divide-by-zero / tiny r
// Lattice energy magnitude ∝ |q1*q2| / r  (Born-Landé / Coulomb proportionality)
// scale to plausible kJ/mol: NaCl q=1,1 r~0.28nm -> ~787. Use constant tuned to that.
const Kconst = 787 * 0.28; // gives U=787 at q1=q2=1, r=0.28
const U = Kconst * (q1 * q2) / r;
const v = H.plot2d({ xMin: 0.15, xMax: 0.7, yMin: 0, yMax: 5000 });
v.grid(); v.axes();
// curve U(r) for current charges
v.fn(x => Kconst * (q1 * q2) / Math.max(x, 0.05), { color: H.colors.accent, width: 3 });
// moving probe sweeping r to show 1/r falloff
const rs = 0.25 + 0.2 * (0.5 + 0.5 * Math.sin(t * 0.8));
const Us = Kconst * (q1 * q2) / rs;
v.dot(rs, Math.min(Us, 5000), { r: 7, fill: H.colors.warn });
v.text("U(r) ∝ q₁q₂/r", 0.42, 4200, { color: H.colors.accent, size: 13 });
// marker at the chosen r
v.line(r, 0, r, Math.min(U, 5000), { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.dot(r, Math.min(U, 5000), { r: 6, fill: H.colors.violet });
// small ion-pair inset, vibrating
const ix = 720, iy = 130;
const vib = 3 * Math.sin(t * 2);
const sep = H.map(r, 0.15, 0.7, 50, 120);
H.circle(ix - sep / 2 - vib, iy, 18, { fill: H.colors.good, stroke: H.colors.ink, width: 1.5 });
H.circle(ix + sep / 2 + vib, iy, 22, { fill: H.colors.warn, stroke: H.colors.ink, width: 1.5 });
H.text("+" + q1, ix - sep / 2 - vib, iy, { color: H.colors.bg, size: 13, align: "center", baseline: "middle", weight: 700 });
H.text("−" + q2, ix + sep / 2 + vib, iy, { color: H.colors.bg, size: 13, align: "center", baseline: "middle", weight: 700 });
H.text("r", ix, iy + 34, { color: H.colors.sub, size: 12, align: "center" });
H.text("Lattice energy: U ∝ q₁q₂ / r", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Higher charges and smaller ions → much stronger ionic lattice", 24, 52, { color: H.colors.sub, size: 13 });
H.text("U ≈ " + U.toFixed(0) + " kJ/mol   (q₁=" + q1 + ", q₂=" + q2 + ", r=" + r.toFixed(2) + " nm)", 24, 74, { color: H.colors.warn, size: 14, weight: 700 });

H.background();
