  H.text("ratio = " + e.r.toFixed(2), x, 314, { color: H.colors.ink, size: 14, align: "center", weight: 700 });
}
const sub = v => { const r = Math.round(v); return r <= 1 ? "" : String(r); };
const formula = "C" + sub(rC) + "H" + sub(rH) + "O" + sub(rO);
H.text("Empirical formula = " + formula, 24, 380, { color: H.colors.accent2, size: 18, weight: 700 });
H.text("(ratios rounded to nearest whole number)", 24, 404, { color: H.colors.sub, size: 12 });

H.background();
const nN2 = Math.max(0, P.molN2);
const nH2 = Math.max(0, P.molH2);
const extN2 = nN2 / 1;
const extH2 = nH2 / 3;
const ext = Math.min(extN2, extH2);
const limiting = extN2 <= extH2 ? "N2" : "H2";
const usedN2 = ext * 1, usedH2 = ext * 3;
const leftN2 = nN2 - usedN2, leftH2 = nH2 - usedH2;
const prodNH3 = ext * 2;
H.text("Limiting reactant:  N2 + 3 H2 -> 2 NH3", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Whichever reactant gives the SMALLER reaction extent runs out first and caps the product.", 24, 52, { color: H.colors.sub, size: 13 });

const prog = 0.5 - 0.5 * Math.cos(t * 1.0);
const bx = 80, bw = 520, bh = 30;
const scaleMax = Math.max(nN2, nH2, prodNH3, 0.001);
function row(y, label, val, col) {
  H.rect(bx, y, bw, bh, { stroke: H.colors.grid, width: 1, radius: 6 });
