const curNH3 = prodNH3 * prog;
row(95, "N2 remaining = " + curN2.toFixed(2) + " mol", curN2, H.colors.accent);
row(150, "H2 remaining = " + curH2.toFixed(2) + " mol", curH2, H.colors.good);
row(205, "NH3 formed = " + curNH3.toFixed(2) + " mol", curNH3, H.colors.violet);

H.text("Limiting reactant: " + limiting, 24, 300, { color: H.colors.warn, size: 16, weight: 700 });
H.text("Reaction extent = " + ext.toFixed(3) + " mol rxn", 24, 326, { color: H.colors.sub, size: 13 });
H.text("Max NH3 = " + prodNH3.toFixed(3) + " mol", 24, 348, { color: H.colors.violet, size: 14, weight: 700 });
H.text("Excess left: N2 " + leftN2.toFixed(2) + " mol, H2 " + leftH2.toFixed(2) + " mol", 24, 372, { color: H.colors.sub, size: 13 });
H.legend([
  { label: "N2", color: H.colors.accent },
