], 640, 100);

H.background();
const theo = Math.max(0.001, P.theoretical);
const actual = Math.max(0, P.actual);
const pct = (actual / theo) * 100;
const shown = Math.min(actual, theo);
H.text("Percent yield = (actual / theoretical) x 100%", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Compares what you really recovered to the stoichiometric maximum; in practice it is below 100%.", 24, 52, { color: H.colors.sub, size: 13 });

const bx = 120, by = 110, bw = 150, bh = 240;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 2, radius: 4 });
