H.line(bx - 14, ly, bx + bw + 14, ly, { color: H.colors.good, width: 2 });
H.text("actual", bx + bw + 18, ly + 4, { color: H.colors.good, size: 12 });

H.text("Theoretical = " + theo.toFixed(2) + " g", 480, 150, { color: H.colors.warn, size: 14, weight: 700 });
H.text("Actual = " + actual.toFixed(2) + " g", 480, 184, { color: H.colors.good, size: 14, weight: 700 });
const pcol = pct > 100 ? H.colors.warn : H.colors.accent2;
H.text("Percent yield = " + pct.toFixed(1) + " %", 480, 230, { color: pcol, size: 20, weight: 700 });
if (pct > 100) H.text("(>100% means impure product or error)", 480, 256, { color: H.colors.warn, size: 12 });
else H.text("lost to side reactions, transfer, purification", 480, 256, { color: H.colors.sub, size: 12 });

