H.background();
const W = H.W, Hh = H.H;
// slider drives "load" / current rate -> animation speed of electrons
const rate = Math.max(0.2, P.rate);
// Beakers
const anX = 200, caX = 700, beY = 320, beW = 150, beH = 170;
H.rect(anX - beW/2, beY, beW, beH, { stroke: H.colors.grid, width: 2, fill: H.colors.panel });
H.rect(caX - beW/2, beY, beW, beH, { stroke: H.colors.grid, width: 2, fill: H.colors.panel });
// Electrodes (vertical bars dipping into solution)
H.rect(anX - 8, 240, 16, 180, { fill: H.colors.sub });
H.rect(caX - 8, 240, 16, 180, { fill: H.colors.accent2 });
// External wire path: top of anode -> up -> across -> down to cathode
const wireY = 150;
H.line(anX, 240, anX, wireY, { color: H.colors.ink, width: 2 });
H.line(anX, wireY, caX, wireY, { color: H.colors.ink, width: 2 });
H.line(caX, wireY, caX, 240, { color: H.colors.ink, width: 2 });
// Electrons travel anode -> cathode along the wire (external circuit)
const N = 6;
for (let i = 0; i < N; i++) {
  const ph = ((t * rate * 0.25) + i / N) % 1;
  // parametrize along the 3-segment wire
  let ex, ey;
  const segUp = 90 / 280, segAcross = 500 / 280; // weights not needed; use length fractions
  // total length: up(90)+across(500)+down(90)=680
  const d = ph * 680;
  if (d < 90) { ex = anX; ey = 240 - d; }
  else if (d < 590) { ex = anX + (d - 90); ey = wireY; }
  else { ex = caX; ey = wireY + (d - 590); }
  H.circle(ex, ey, 5, { fill: H.colors.yellow });
}
// e- direction label + arrow
H.arrow(380, wireY, 470, wireY, { color: H.colors.yellow, width: 2 });
H.text("e-", 420, wireY - 12, { color: H.colors.yellow, size: 13, align: "center" });
// Salt bridge connecting the two solutions (inverted U)
const sbY = 280;
H.path([[anX, sbY], [anX, sbY - 30], [caX, sbY - 30], [caX, sbY]], { color: H.colors.violet, width: 8 });
H.text("salt bridge", (anX + caX) / 2, sbY - 42, { color: H.colors.violet, size: 12, align: "center" });
// ions in salt bridge: cations -> cathode, anions -> anode
const ip = (t * rate * 0.3) % 1;
H.circle(anX + (caX - anX) * ip, sbY - 30, 4, { fill: H.colors.accent }); // cation -> cathode
H.circle(caX - (caX - anX) * ip, sbY - 30, 4, { fill: H.colors.warn });   // anion -> anode
// Labels
H.text("Galvanic cell:  e- flow anode -> cathode through wire", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Anode = oxidation (-);  Cathode = reduction (+);  salt bridge keeps charge balance", 24, 52, { color: H.colors.sub, size: 13 });
H.text("ANODE (-)", anX, 470, { color: H.colors.sub, size: 13, align: "center", weight: 700 });
H.text("oxidation: M -> M^n+ + n e-", anX, 488, { color: H.colors.sub, size: 11, align: "center" });
H.text("CATHODE (+)", caX, 470, { color: H.colors.accent2, size: 13, align: "center", weight: 700 });
H.text("reduction: M^n+ + n e- -> M", caX, 488, { color: H.colors.accent2, size: 11, align: "center" });
H.text("relative current (slider) = " + rate.toFixed(1) + "x", 24, 76, { color: H.colors.yellow, size: 13 });

H.background();
const Ecat = P.Ecat, Ean = P.Ean; // standard reduction potentials, V
