H.text(Ecell > 0 ? "E_cell > 0 -> galvanic (spontaneous, dG<0)" : (Ecell < 0 ? "E_cell < 0 -> electrolytic (non-spontaneous)" : "E_cell = 0 -> at equilibrium"), 24, 116, { color: H.colors.sub, size: 13 });

H.background();
// Nernst: E = E0 - (RT/nF) ln Q, here Q = [products]/[reactants] for a
// concentration cell-style readout. Daniell cell Zn|Zn2+||Cu2+|Cu, E0=+1.10 V.
const E0 = 1.10;
const n = 2;            // electrons transferred
