const Cprod = Math.max(0.001, P.Cprod);  // [Zn2+] (product side)
const Creact = Math.max(0.001, P.Creact); // [Cu2+] (reactant side)
// Q = [Zn2+]/[Cu2+]; reaction quotient
const v = H.plot2d({ xMin: -4, xMax: 3, yMin: 0.9, yMax: 1.3 });
v.grid(); v.axes();
// E as a function of log10(Q): straight line. x-axis = log10 Q.
const slope = -(RTF / n) * Math.LN10; // dE/d(log10 Q)
v.fn(x => E0 + slope * x, { color: H.colors.accent, width: 3 });
// live point: current Q from sliders, but let the marker breathe along the line
const Qnow = Cprod / Creact;
const logQ = Math.log10(Qnow);
const Enow = E0 - (RTF / n) * Math.log(Qnow);
// animate a probe sweeping the line so MOVE rule holds
const sweep = -1 + 2.5 * Math.sin(t * 0.7);
const Esweep = E0 + slope * sweep;
v.dot(sweep, Esweep, { r: 5, fill: H.colors.sub });
v.dot(logQ, Enow, { r: 7, fill: H.colors.warn });
v.text("E0 = +1.10 V", -3.8, 1.27);
