H.text("Daniell cell Zn|Zn2+||Cu2+|Cu, n=2, T=298 K; x-axis = log10 Q", 24, 52, { color: H.colors.sub, size: 13 });
H.text("Q = [Zn2+]/[Cu2+] = " + Qnow.toFixed(3) + "   E = " + Enow.toFixed(3) + " V", 24, 74, { color: H.colors.warn, size: 13 });

H.background();
// Faraday electrolysis: moles deposited = I*t / (n*F).
// Example: Cu2+ + 2e- -> Cu, n=2, M(Cu)=63.55 g/mol.
const F = 96485;          // C/mol e-
const n = 2;              // electrons per Cu atom
const M = 63.55;          // g/mol Cu
const I = Math.max(0, P.I);     // current in A
const tmax = Math.max(1, P.tmax); // total run time in s
// animate elapsed time looping 0..tmax
const elapsed = (t % 6) / 6 * tmax;
const charge = I * elapsed;            // Q = I t
const molEl = charge / F;              // moles of electrons
const molCu = molEl / n;               // moles of Cu
const massCu = molCu * M;              // grams deposited
// growing bar of deposited mass; full bar = mass at tmax
const massFull = (I * tmax / F) / n * M;
const v = H.plot2d({ xMin: 0, xMax: Math.max(tmax, 1), yMin: 0, yMax: Math.max(massFull * 1.2, 0.01) });
v.grid(); v.axes();
// curve mass(t') = I t' /(nF) * M  -> straight line through origin
v.fn(x => (I * x / F) / n * M, { color: H.colors.accent, width: 3 });
v.dot(elapsed, massCu, { r: 7, fill: H.colors.warn });
v.line(elapsed, 0, elapsed, massCu, { color: H.colors.sub, width: 1, dash: [3, 3] });
v.text("Cu2+ + 2e- -> Cu", 0.2 * Math.max(tmax,1), Math.max(massFull * 1.1, 0.009));
H.text("Faraday: n_Cu = I*t / (n*F)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("I=" + I.toFixed(1) + " A, t up to " + tmax.toFixed(0) + " s; F=96485 C/mol, n=2", 24, 52, { color: H.colors.sub, size: 13 });
H.text("t=" + elapsed.toFixed(0) + " s  Q=" + charge.toFixed(0) + " C  mol Cu=" + molCu.toFixed(4) + "  mass=" + massCu.toFixed(3) + " g", 24, 74, { color: H.colors.warn, size: 13 });

H.background();
// Oxidation states: rules (O = -2, H = +1) force the central atom's number.
// Slider picks a sulfur compound; oxidation number of S is computed so the
// sum of oxidation numbers = overall charge (here neutral, sum = 0).
// Compounds: H2S, S8, SO2, SO3, H2SO4 with S oxidation states -2,0,+4,+6,+6.
const comps = [
  { f: "H2S",   parts: [["H", 2, +1], ["S", 1, null]], charge: 0 },
  { f: "S8",    parts: [["S", 8, null]],               charge: 0 },
  { f: "SO2",   parts: [["O", 2, -2], ["S", 1, null]], charge: 0 },
  { f: "SO3",   parts: [["O", 3, -2], ["S", 1, null]], charge: 0 },
  { f: "H2SO4", parts: [["H", 2, +1], ["O", 4, -2], ["S", 1, null]], charge: 0 }
];
const idx = Math.max(0, Math.min(comps.length - 1, Math.round(P.compound)));
const c = comps[idx];
// solve for the unknown (S) oxidation number
let known = 0, sCount = 1;
for (const p of c.parts) { if (p[2] !== null) known += p[1] * p[2]; else sCount = p[1]; }
const oxS = (c.charge - known) / sCount;
// layout boxes for each element, animate a highlight that sweeps the unknown
const cx = H.W / 2, cy = H.H / 2;
H.rect(cx - 220, cy - 70, 440, 140, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
let x = cx - 170;
for (const p of c.parts) {
  const val = p[2] !== null ? p[2] : oxS;
  const col = p[2] === null ? H.colors.warn : H.colors.accent;
  const pulse = p[2] === null ? (0.5 + 0.5 * Math.sin(t * 3)) : 1;
  H.circle(x, cy + 8, 26, { fill: H.colors.bg, stroke: col, width: 2 + 2 * pulse });
  H.text(p[0] + (p[1] > 1 ? p[1] : ""), x, cy + 8, { color: H.colors.ink, size: 20, weight: 700, align: "center", baseline: "middle" });
  const sign = val >= 0 ? "+" : "";
  H.text(sign + val, x, cy - 40, { color: col, size: 16, weight: 700, align: "center" });
  x += 110;
}
H.text("Oxidation numbers: sum = overall charge", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Rules: O = -2, H = +1; solve the rest. Compound: " + c.f, 24, 52, { color: H.colors.sub, size: 13 });
H.text("S in " + c.f + " = " + (oxS >= 0 ? "+" : "") + oxS + "  (sum of all = " + c.charge + ")", 24, 74, { color: H.colors.warn, size: 13 });

H.background();
// Percent composition: mass% of element X = (n_X * A_X) / M_molar * 100%.
// Compound family C_a H_b O_c (e.g. glucose-like). Sliders set subscripts a,c
// (carbon and oxygen counts); hydrogen fixed at 2*a (a CH2O-style unit).
const Ac = 12.011, Ah = 1.008, Ao = 15.999; // atomic masses g/mol
const a = Math.max(1, Math.round(P.a));   // # carbon
const c = Math.max(0, Math.round(P.c));   // # oxygen
const b = 2 * a;                          // # hydrogen (CH2O repeat)
const mC = a * Ac, mH = b * Ah, mO = c * Ao;
const M = Math.max(1e-6, mC + mH + mO);   // molar mass
const pC = mC / M * 100, pH = mH / M * 100, pO = mO / M * 100;
// animated stacked bar: a sweeping marker rides the cumulative boundaries
const x0 = 120, x1 = H.W - 60, y = H.H / 2, bh = 70;
const segs = [
  { p: pC, col: H.colors.accent, lab: "C" },
  { p: pH, col: H.colors.good, lab: "H" },
  { p: pO, col: H.colors.warn, lab: "O" }
];
let cx = x0;
for (const s of segs) {
  const w = (s.p / 100) * (x1 - x0);
  H.rect(cx, y - bh / 2, Math.max(0, w), bh, { fill: s.col, stroke: H.colors.bg, width: 1 });
  if (w > 24) H.text(s.lab + " " + s.p.toFixed(1) + "%", cx + w / 2, y, { color: H.colors.bg, size: 13, weight: 700, align: "center", baseline: "middle" });
  cx += w;
}
// sweeping probe along the bar
const px = x0 + (0.5 + 0.5 * Math.sin(t * 0.8)) * (x1 - x0);
H.line(px, y - bh / 2 - 14, px, y + bh / 2 + 14, { color: H.colors.ink, width: 2 });
const formula = "C" + a + "H" + b + (c > 0 ? "O" + c : "");
H.text("Percent composition: %X = n_X * A_X / M * 100", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Formula " + formula + ",  M = " + M.toFixed(2) + " g/mol", 24, 52, { color: H.colors.sub, size: 13 });
H.text("%C=" + pC.toFixed(1) + "  %H=" + pH.toFixed(1) + "  %O=" + pO.toFixed(1) + "  (sum=" + (pC + pH + pO).toFixed(1) + ")", 24, 74, { color: H.colors.warn, size: 13 });

H.background();
// Mole-ratio stoichiometry: for a A + b B -> products, the moles of product
// from the limiting reactant follow the balanced coefficients.
// Reaction: N2 + 3 H2 -> 2 NH3. Slider sets the H2 coefficient b and the
// supplied moles of H2; N2 assumed in excess so H2 is limiting.
const a = 1;                              // N2 coefficient (fixed)
const b = Math.max(1, Math.round(P.b));   // H2 coefficient
const prodCoef = 2;                       // NH3 coefficient (fixed)
const molH2 = Math.max(0, P.molH2);       // supplied moles of H2
// product moles = molH2 * (prodCoef / b)
const molNH3full = molH2 * (prodCoef / b);
// animate the reaction filling up over a loop
const prog = (t % 5) / 5;                 // 0..1 extent of reaction
const molNH3 = molNH3full * prog;
const H2used = molH2 * prog;
const v = H.plot2d({ xMin: 0, xMax: 1, yMin: 0, yMax: Math.max(molH2, molNH3full, 0.01) * 1.2 });
v.grid(); v.axes();
// H2 consumed (down) and NH3 formed (up) vs reaction extent
v.fn(x => molH2 * (1 - x), { color: H.colors.warn, width: 3 });   // H2 remaining
v.fn(x => molNH3full * x, { color: H.colors.good, width: 3 });    // NH3 formed
v.dot(prog, molH2 - H2used, { r: 6, fill: H.colors.warn });
v.dot(prog, molNH3, { r: 6, fill: H.colors.good });
v.text("N2 + " + b + " H2 -> 2 NH3", 0.05, Math.max(molH2, molNH3full, 0.01) * 1.12);
H.legend([{ label: "H2 left", color: H.colors.warn }, { label: "NH3 made", color: H.colors.good }], H.W - 170, 70);
H.text("Mole ratio: n_NH3 = n_H2 * (2 / " + b + ")", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Limiting H2 = " + molH2.toFixed(2) + " mol; x-axis = reaction extent (0..1)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("extent=" + prog.toFixed(2) + "  NH3=" + molNH3.toFixed(2) + " mol  (max " + molNH3full.toFixed(2) + " mol)", 24, 74, { color: H.colors.warn, size: 13 });

H.background();
