H.background();
const W = H.W, Hh = H.H;
const Ea = P.Ea;
const dH = -40;
const x0 = 90, x1 = W - 90;
const baseY = Hh - 120;
const kjToPx = 1.6;
const yReact = baseY;
const yProd = baseY + dH * kjToPx;
const yPeak = baseY - Ea * kjToPx;
const pts = [];
const N = 120;
for (let i = 0; i <= N; i++) {
  const f = i / N;
  const px = x0 + f * (x1 - x0);
  let py;
  if (f < 0.2) py = yReact;
  else if (f > 0.8) py = yProd;
  else {
    const u = (f - 0.2) / 0.6;
    const bump = Math.sin(Math.PI * u);
    const baseLine = yReact + (yProd - yReact) * u;
    py = baseLine - (baseLine - yPeak) * bump;
  }
  pts.push([px, py]);
}
H.path(pts, { color: H.colors.accent, width: 3 });
H.line(x0, 50, x0, Hh - 60, { color: H.colors.axis, width: 2 });
H.line(x0, Hh - 60, x1, Hh - 60, { color: H.colors.axis, width: 2 });
H.text("energy (kJ/mol)", x0 + 6, 46, { color: H.colors.sub, size: 12 });
H.text("reaction coordinate", x1 - 10, Hh - 40, { color: H.colors.sub, size: 12, align: "right" });
const f = 0.2 + 0.6 * (0.5 - 0.5 * Math.cos(t * 1.2));
const idx = Math.min(N, Math.max(0, Math.round(f * N)));
const mk = pts[idx];
H.circle(mk[0], mk[1], 9, { fill: H.colors.warn, stroke: H.colors.ink, width: 1 });
H.line(x0, yReact, x0 + 70, yReact, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.line(x1 - 70, yProd, x1, yProd, { color: H.colors.grid, width: 1, dash: [4, 4] });
