// Clausius-Clapeyron: ln(P) = -dHvap/R * (1/T) + C.  Water-like values.
const dH = 40700;          // enthalpy of vaporization (J/mol), ~water
const R = 8.314;           // J/(mol K)
const Tb = 373.15;         // normal boiling point (K), P = 101.3 kPa there
const P0 = 101.3;          // kPa at Tb
// C from boundary: ln(P0) = -dH/R / Tb + C
const Cc = Math.log(P0) + dH / R / Tb;
function Pvap(Tk){ return Math.exp(-dH / R / Math.max(Tk,1) + Cc); } // kPa
