H.background();
// Weak acid: % ionization = ([H+]/C)*100. As C decreases (dilution), % rises (Ostwald).
// Exact: x^2/(C-x)=Ka  => x=(-Ka+sqrt(Ka^2+4 Ka C))/2 ; %ion = x/C*100
const Ka = 1.8e-5;          // acetic acid
function pctIon(C){
  const Cc = Math.max(C, 1e-6);
  const x = (-Ka + Math.sqrt(Ka*Ka + 4*Ka*Cc)) / 2;
  return Math.min(x / Cc * 100, 100);
}
// plot % ionization vs concentration on log axis (use log10 C as x)
const lcMin = -5, lcMax = 0;   // C from 1e-5 to 1 mol/L
const v = H.plot2d({ xMin: lcMin, xMax: lcMax, yMin: 0, yMax: 100 });
v.grid(); v.axes();
v.fn(lc => pctIon(Math.pow(10, lc)), { color: H.colors.accent, width: 3 });
// user slider: concentration C (mol/L)
const C = Math.max(Math.min(P.C, 1), 1e-5);
const lcU = Math.log10(C);
const pu = pctIon(C);
v.dot(lcU, pu, { r: 6, fill: H.colors.good });
v.line(lcU, 0, lcU, pu, { color: H.colors.good, width: 1, dash: [3,3] });
// animated probe sweeping concentration (loops within range)
const lca = lcMin + (0.5 - 0.5 * Math.cos(t * 0.6)) * (lcMax - lcMin);
v.dot(lca, pctIon(Math.pow(10, lca)), { r: 6, fill: H.colors.accent2 });
H.text("Percent ionization rises on dilution (Ostwald)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("x-axis = log10(C); more dilute (left) -> larger % ionized", 24, 50, { color: H.colors.sub, size: 13 });
H.text("Ka (acetic) = 1.8e-5", 24, 470, { color: H.colors.sub, size: 13 });
H.text("C = " + C.toExponential(1) + " M  ->  % ionized = " + pu.toFixed(2) + " %", 24, 490, { color: H.colors.good, size: 13 });
H.text("[H+] = " + (pu/100*C).toExponential(2) + " M,  pH = " + (-Math.log10(Math.max(pu/100*C,1e-14))).toFixed(2), 24, 510, { color: H.colors.sub, size: 13 });

H.background();
// Buffer: Henderson-Hasselbalch. pH = pKa + log([A-]/[HA]).
// Start with equal moles HA and A- (1 L). Add strong base 'b' mol (converts HA->A-)
// or strong acid (b<0, converts A-->HA). Compare to adding same to pure water.
const pKa = 4.74;          // acetic / acetate buffer
const n0 = 0.50;           // initial moles HA = moles A- (in 1 L)
function pHbuf(b){
  // b = mol strong base added (negative = strong acid)
  const HA = n0 - b;
  const A  = n0 + b;
  if (HA <= 1e-6) return 7 + 6;          // past capacity (base side) -> jumps up
  if (A  <= 1e-6) return 1;              // past capacity (acid side) -> jumps down
  return pKa + Math.log10(A / HA);
}
function pHwater(b){
  // adding b mol strong base (or acid) to 1 L pure water
  if (b > 0){ const OH = b; const pOH = -Math.log10(Math.max(OH,1e-14)); return 14 - pOH; }
  if (b < 0){ const Hc = -b; return -Math.log10(Math.max(Hc,1e-14)); }
  return 7;
}
const bMin = -0.5, bMax = 0.5;
const v = H.plot2d({ xMin: bMin, xMax: bMax, yMin: 0, yMax: 14 });
v.grid(); v.axes();
v.fn(b => Math.max(Math.min(pHwater(b),14),0), { color: H.colors.warn, width: 2 });
v.fn(b => Math.max(Math.min(pHbuf(b),14),0), { color: H.colors.accent, width: 3 });
v.line(bMin, pKa, bMax, pKa, { color: H.colors.sub, width: 1, dash: [5,5] });
v.text("pKa = " + pKa.toFixed(2), bMin + 0.02, pKa + 0.7, { color: H.colors.sub, size: 12 });
H.legend([{label:"buffer", color:H.colors.accent},{label:"pure water", color:H.colors.warn}], 660, 70);
// user slider: added strong base (mol); negative = added acid
const b = Math.max(Math.min(P.b, bMax), bMin);
v.dot(b, Math.max(Math.min(pHbuf(b),14),0), { r: 6, fill: H.colors.good });
// animated probe sweeping additions (loops within capacity-ish range)
const ba = (bMax * 0.85) * Math.sin(t * 0.6);
v.dot(ba, Math.max(Math.min(pHbuf(ba),14),0), { r: 6, fill: H.colors.accent2 });
H.text("Buffer capacity: pH = pKa + log([A-]/[HA])", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Add acid/base: buffer pH barely moves until reserves run out", 24, 50, { color: H.colors.sub, size: 13 });
H.text("HA0 = A-0 = " + n0.toFixed(2) + " mol in 1 L", 24, 470, { color: H.colors.sub, size: 13 });
H.text("add base = " + b.toFixed(2) + " mol  ->  buffer pH = " + pHbuf(b).toFixed(2), 24, 490, { color: H.colors.good, size: 13 });
H.text("same to pure water -> pH = " + pHwater(b).toFixed(2) + "  (delta = " + Math.abs(pHbuf(b)-pHwater(b)).toFixed(1) + ")", 24, 510, { color: H.colors.sub, size: 13 });
